// Preview transport (#528/#530): bundle a UI skeleton (in-memory files) with
// esbuild-wasm and produce the srcdoc for a sandboxed iframe. React/three are kept
// external and resolved in the iframe via an esm.sh import-map (the chosen approach).
//
// The esbuild call is isolated; the path resolution, bootstrap, and srcdoc assembly
// are pure so they're unit-testable without the wasm runtime.

// Type-only import — the esbuild-wasm runtime is dynamically imported in
// ensureEsbuild() so the module's load-time invariant (which fails under jsdom)
// never runs in tests, and the pure helpers below stay importable.
import type * as Esbuild from "esbuild-wasm";
import wasmURL from "esbuild-wasm/esbuild.wasm?url";
import importmapEmbedded from "@data/ui/preview-importmap.json";
import { PREVIEW_SHIM_NAMESPACE, shimModuleFor, scanStubImports, previewCspMeta } from "@/shared/lib/preview/previewShims";
// #79 — ONE loader rule for both bundlers. This copy had drifted to the opposite extensionless
// default, so the same module could build differently depending on which preview reached it.
import {
  loaderFor, PREVIEW_DEFINE, PREVIEW_GLOB_BANNER, PREVIEW_RAW_NAMESPACE, rawImportSpec, rawModuleSource,
  rawModuleText, type MemLoader,
} from "@/shared/lib/preview/componentBundle";

/** esm.sh import-map for the externals (pinned; `deps` params keep React deduped) — the pins live in
 *  `@data/ui/preview-importmap.json` (#2419; ONE source, also read by streamingRuntime.ts), a plain
 *  embedded import like its `@data/ui/*` neighbors. */
export const DEFAULT_IMPORTMAP: Record<string, string> = importmapEmbedded;

/** Bare specifiers left external — resolved in the iframe by the import-map (derived from its keys
 *  so the two can never drift). */
export const PREVIEW_EXTERNALS = Object.keys(DEFAULT_IMPORTMAP);

const BOOTSTRAP_ENTRY = "__preview_bootstrap__.jsx";

/** The synthetic entry that mounts the skeleton's screen component into #root. */
export function bootstrapSource(screenEntry: string): string {
  const spec = screenEntry.startsWith(".") ? screenEntry : `./${screenEntry}`;
  return `import { createRoot } from "react-dom/client";\nimport Screen from "${spec}";\ncreateRoot(document.getElementById("root")).render(<Screen />);\n`;
}

/** The index suffixes this bundler's `lookupMem` appends for a bare DIRECTORY id. Kept beside the
 *  resolver so the two cannot disagree about what "index-backed" means. */
const INDEX_SUFFIXES = ["/index.tsx", "/index.ts", "/index.jsx"] as const;

/**
 * Resolve a relative import against its importer's directory. Pure.
 *
 * SECOND COPY of the shared bundler's resolver (`shared/lib/preview/componentBundle.ts`) and it carried
 * the SAME bug, so it gets the same fix (#a-barrel-import-resolves-against-its-own-directory): an
 * importer that is only reachable through an index suffix is a DIRECTORY, and is its own `fromDir`.
 * Stripping its last segment sent a barrel's `./theme` one level too high, to a module that does not
 * exist.
 *
 * That the two copies exist at all is the real finding — a fix in one is not a fix. Unifying them is
 * filed separately rather than smuggled into a bug fix.
 */
export function resolveMemPath(importer: string, spec: string, files?: Record<string, string>): string {
  const isDirId =
    !!files && files[importer] == null && INDEX_SUFFIXES.some((s) => files[importer + s] != null);
  const fromDir = isDirId
    ? importer
    : importer.includes("/")
      ? importer.slice(0, importer.lastIndexOf("/"))
      : "";
  const parts = (fromDir ? fromDir.split("/") : []).concat(spec.split("/"));
  const out: string[] = [];
  for (const p of parts) {
    if (p === "" || p === ".") continue;
    if (p === "..") out.pop();
    else out.push(p);
  }
  return out.join("/");
}

/**
 * Look up an in-memory file, trying common extensions. Pure.
 *
 * The loader choice is IMPORTED from the shared bundler rather than restated (#79). This copy had
 * drifted the other way — it defaulted an extensionless key to `jsx`, where the shared one had
 * already been corrected to `tsx` under #3549 — so the same module built here and there could pick
 * different loaders. Two copies of a rule are two rules; sharing the one function is what stops this
 * from being rediscovered a third time.
 */
export function lookupMem(files: Record<string, string>, path: string): { contents: string; loader: MemLoader } | null {
  for (const ext of ["", ".tsx", ".ts", ".jsx", ".js", "/index.tsx", "/index.jsx"]) {
    const key = path + ext;
    if (files[key] != null) {
      return { contents: files[key], loader: loaderFor(key, files[key]) };
    }
  }
  return null;
}

let initPromise: Promise<typeof Esbuild> | null = null;
function ensureEsbuild(): Promise<typeof Esbuild> {
  if (!initPromise) {
    initPromise = import("esbuild-wasm").then(async (m) => {
      await m.initialize({ wasmURL, worker: true });
      return m;
    });
  }
  return initPromise;
}

function inMemoryPlugin(files: Record<string, string>): Esbuild.Plugin {
  const stubExports = scanStubImports(files, (s) => PREVIEW_EXTERNALS.includes(s)); // #3696 — names per stubbed package
  return {
    name: "preview-mem",
    setup(build) {
      build.onResolve({ filter: /.*/ }, (args) => {
        if (args.kind === "entry-point") return { path: BOOTSTRAP_ENTRY, namespace: "mem" };
        // #85 — the same `?raw` / `?url` rule the component bundler uses, IMPORTED not restated (the two
        // copies of the loader rule drifted to opposite defaults once already, #79). Before the externals
        // check: the query makes a suffixed specifier match nothing, so it would otherwise be stubbed.
        if (rawImportSpec(args.path)) return { path: args.path, namespace: PREVIEW_RAW_NAMESPACE };
        if (PREVIEW_EXTERNALS.includes(args.path)) return { path: args.path, external: true };
        if (args.path.startsWith(".")) return { path: resolveMemPath(args.importer, args.path, files), namespace: "mem" };
        // #3696: any OTHER bare import resolves to a bundled-in LOCAL shim/stub (never esm.sh at large), so a
        // skeleton that pulls in a native/npm package still bundles + renders instead of failing to resolve.
        return { path: args.path, namespace: PREVIEW_SHIM_NAMESPACE };
      });
      build.onLoad({ filter: /.*/, namespace: PREVIEW_SHIM_NAMESPACE }, (args) => ({ contents: shimModuleFor(args.path, stubExports.get(args.path)), loader: "js" }));
      build.onLoad({ filter: /.*/, namespace: PREVIEW_RAW_NAMESPACE }, (args) => ({ contents: rawModuleSource(rawModuleText(files, args.path)), loader: "js" }));
      build.onLoad({ filter: /.*/, namespace: "mem" }, (args) => {
        const hit = lookupMem(files, args.path);
        if (!hit) return { errors: [{ text: `preview: module not found: ${args.path}` }] };
        return { contents: hit.contents, loader: hit.loader };
      });
    },
  };
}

/**
 * Bundle a UI skeleton into a single ESM module that mounts `screenEntry` into #root.
 * `files` is relpath → source (the .ui-skeleton folder, in memory). React/three stay
 * external. Throws on a build error (caller surfaces it).
 */
export async function bundleSkeleton(files: Record<string, string>, screenEntry: string): Promise<string> {
  const esbuild = await ensureEsbuild();
  const withBootstrap = { ...files, [BOOTSTRAP_ENTRY]: bootstrapSource(screenEntry) };
  const result = await esbuild.build({
    entryPoints: [BOOTSTRAP_ENTRY],
    bundle: true,
    format: "esm",
    write: false,
    jsx: "automatic",
    logLevel: "silent",
    // #81 — the same `import.meta.glob` shim the component bundler uses, IMPORTED not restated. The
    // two copies of the loader rule drifted to opposite defaults (#79); this one is shared by design.
    define: PREVIEW_DEFINE,
    banner: { js: PREVIEW_GLOB_BANNER },
    plugins: [inMemoryPlugin(withBootstrap)],
  });
  return result.outputFiles?.[0]?.text ?? "";
}

/**
 * Assemble the sandboxed-iframe srcdoc: import-map for the externals + the bundle as a
 * module, with error/ready signals posted to the parent. Pure.
 */
export function buildPreviewSrcDoc(bundleJs: string, importmap: Record<string, string> = DEFAULT_IMPORTMAP): string {
  return `<!doctype html><html><head><meta charset="utf-8" />
${previewCspMeta()}
<style>html,body,#root{margin:0;height:100%;background:var(--bg, #0d0d0f);font-family:Inter,system-ui,sans-serif;color:#eee}</style>
<script type="importmap">${JSON.stringify({ imports: importmap })}</script>
</head><body><div id="root"></div>
<script>
  window.addEventListener("error", (e) => parent.postMessage({ __preview: "error", message: String(e.message) }, "*"));
  window.addEventListener("unhandledrejection", (e) => parent.postMessage({ __preview: "error", message: String(e.reason) }, "*"));
</script>
<script type="module">
${bundleJs}
parent.postMessage({ __preview: "ready" }, "*");
</script>
</body></html>`;
}

